/**
 * Read-only census of the COMPLETE world currently generated by the game.
 * This never creates a test region and never changes gameplay map data.
 *
 * npm run audit:world
 * node scripts/audit-world-integrity.mjs --seed 1337 --output output/reports/world-integrity.json
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import WorldGenerator from '../js/world/world-generator.js';
import { TERRAIN, FLAGS } from '../js/world/map-data.js';

const REQUIRED_LAYERS = Object.freeze({
  terrain: Uint8Array,
  heightMap: Uint16Array,
  flags: Uint16Array,
  owner: Uint16Array,
  fog: Uint8Array,
});
const TERRAIN_NAMES = new Map(Object.entries(TERRAIN).map(([name, code]) => [code, name]));

function fnv32(layer) {
  let h = 2166136261;
  if (!layer) return null;
  for (let i = 0; i < layer.length; i++) {
    const n = layer[i];
    h ^= n & 255;
    h = Math.imul(h, 16777619);
    h ^= (n >>> 8) & 255;
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

export function auditWorldData(world) {
  const errors = [];
  const warnings = [];
  const width = world?.width;
  const height = world?.height;
  const validDimensions = Number.isSafeInteger(width) && Number.isSafeInteger(height) && width > 0 && height > 0;
  const count = validDimensions ? width * height : 0;
  const add = (list, code, detail) => {
    if (list.length < 30) list.push({ code, detail });
  };

  if (!validDimensions || !Number.isSafeInteger(count)) {
    add(errors, 'INVALID_DIMENSIONS', { width, height });
  }
  const layers = {};
  for (const [name, Type] of Object.entries(REQUIRED_LAYERS)) {
    const value = world?.[name];
    const valid = value instanceof Type && value.length === count && count > 0;
    layers[name] = { type: value?.constructor?.name ?? null, length: value?.length ?? null, valid };
    if (!valid) add(errors, 'INVALID_LAYER', { layer: name, expectedType: Type.name, expectedLength: count });
  }
  if (world?.biomes != null && (!(world.biomes instanceof Uint8Array) || world.biomes.length !== count)) {
    add(errors, 'INVALID_BIOME_LAYER', { length: world.biomes?.length ?? null, expectedLength: count });
  }
  if (world?.politicalOwnerMap != null && (!(world.politicalOwnerMap instanceof Uint8Array) || world.politicalOwnerMap.length !== count)) {
    add(errors, 'INVALID_POLITICAL_OWNER_LAYER', { length: world.politicalOwnerMap?.length ?? null, expectedLength: count });
  }
  const geometry = {};
  const terrain = {};
  const flags = { roads: 0, rivers: 0, settlements: 0, forests: 0, mountains: 0 };
  let invalidTerrainTiles = 0;
  let nonzeroOwnerTiles = 0;
  let nonzeroPoliticalTiles = 0;
  let h = 2166136261;

  if (layers.terrain.valid) {
    for (let i = 0; i < count; i++) {
      const id = world.terrain[i];
      const label = TERRAIN_NAMES.get(id);
      if (label) terrain[label] = (terrain[label] || 0) + 1;
      else invalidTerrainTiles++;
      const mask = layers.flags.valid ? world.flags[i] : 0;
      if (mask & FLAGS.ROAD) flags.roads++;
      if (mask & FLAGS.RIVER) flags.rivers++;
      if (mask & FLAGS.SETTLEMENT) flags.settlements++;
      if (mask & FLAGS.FOREST) flags.forests++;
      if (mask & FLAGS.MOUNTAIN) flags.mountains++;
      if (layers.owner.valid && world.owner[i] !== 0) nonzeroOwnerTiles++;
      if (world.politicalOwnerMap instanceof Uint8Array && world.politicalOwnerMap.length === count && world.politicalOwnerMap[i] !== 0) nonzeroPoliticalTiles++;
      h ^= id;
      h = Math.imul(h, 16777619);
    }
  }
  if (invalidTerrainTiles) add(errors, 'UNKNOWN_TERRAIN_IDS', { count: invalidTerrainTiles });

  const isInBounds = (p) =>
    p && Number.isInteger(p.x) && Number.isInteger(p.y) &&
    p.x >= 0 && p.y >= 0 && p.x < width && p.y < height;
  const coordinates = (item) => ({
    x: Number.isFinite(item?.tx) ? item.tx : item?.x,
    y: Number.isFinite(item?.ty) ? item.ty : item?.y,
  });
  function scanPoints(kind, points) {
    let invalid = 0;
    for (const point of points) {
      if (!isInBounds(point)) {
        invalid++;
        if (invalid <= 4) add(errors, 'OUT_OF_BOUNDS_' + kind.toUpperCase(), { point });
      }
    }
    return { points: points.length, outOfBounds: invalid };
  }

  const settlements = Array.isArray(world?.settlements) ? world.settlements : [];
  const ids = new Set();
  const types = {};
  const factions = {};
  let duplicateSettlementIds = 0;
  let missingSettlementIds = 0;
  for (const settlement of settlements) {
    if (settlement?.id == null) {
      missingSettlementIds++;
    } else if (ids.has(String(settlement.id))) {
      duplicateSettlementIds++;
    } else {
      ids.add(String(settlement.id));
    }
    const type = String(settlement?.type || 'unknown');
    const owner = String(settlement?.owner || 'unassigned');
    types[type] = (types[type] || 0) + 1;
    factions[owner] = (factions[owner] || 0) + 1;
  }
  if (duplicateSettlementIds) add(errors, 'DUPLICATE_SETTLEMENT_IDS', { count: duplicateSettlementIds });
  if (missingSettlementIds) add(errors, 'MISSING_SETTLEMENT_IDS', { count: missingSettlementIds });
  geometry.settlements = scanPoints('settlement', settlements.map(coordinates));

  const roads = Array.isArray(world?.roads) ? world.roads : [];
  const rivers = Array.isArray(world?.rivers) ? world.rivers : [];
  const crossings = Array.isArray(world?.crossings) ? world.crossings : [];
  const roadPoints = roads.flatMap((r) => Array.isArray(r?.path) ? r.path : []);
  const riverPoints = rivers.flatMap((r) => Array.isArray(r) ? r : []);
  geometry.roads = { segments: roads.length, ...scanPoints('road', roadPoints) };
  geometry.rivers = { segments: rivers.length, ...scanPoints('river', riverPoints) };
  geometry.crossings = scanPoints('crossing', crossings);
  let orphanRoadEndpoints = 0;
  for (const road of roads) {
    if (!Array.isArray(road?.path) || road.path.length === 0) {
      add(errors, 'EMPTY_ROAD_PATH', { from: road?.from ?? null, to: road?.to ?? null });
    }
    if (road?.from != null && !ids.has(String(road.from))) orphanRoadEndpoints++;
    if (road?.to != null && !ids.has(String(road.to))) orphanRoadEndpoints++;
  }
  if (orphanRoadEndpoints) add(errors, 'ORPHAN_ROAD_ENDPOINTS', { count: orphanRoadEndpoints });

  const riverPointsSet = new Set(riverPoints.filter(isInBounds).map(p => String(p.x) + ',' + String(p.y)));
  const crossingsWithoutRiver = crossings.filter(p => isInBounds(p) && !riverPointsSet.has(String(p.x) + ',' + String(p.y))).length;
  if (crossingsWithoutRiver) add(warnings, 'CROSSINGS_WITHOUT_RIVER_POINT', { count: crossingsWithoutRiver });

  if (settlements.length === 0) add(warnings, 'NO_SETTLEMENTS', {});
  if (roads.length === 0) add(warnings, 'NO_ROADS', {});
  if (rivers.length === 0) add(warnings, 'NO_RIVERS', {});
  if (count > 0 && nonzeroOwnerTiles === 0) add(warnings, 'TILE_OWNERS_UNASSIGNED', {});
  if (!world?.politicalOwnerMap) add(warnings, 'NO_POLITICAL_OWNER_MAP', {});

  return {
    schemaVersion: 'world-integrity-v1',
    scope: 'entire-current-world; not a world-data pilot',
    seed: world?.seed ?? null,
    dimensions: { width: width ?? null, height: height ?? null, tiles: count },
    layers,
    terrainTiles: terrain,
    invalidTerrainTiles,
    flagTiles: flags,
    ownership: {
      nonzeroTileOwnerCount: nonzeroOwnerTiles,
      nonzeroPoliticalOwnerCount: nonzeroPoliticalTiles,
      politicalOwnerIds: world?.politicalOwnerIds ?? [],
    },
    settlements: { count: settlements.length, types, factions, duplicateSettlementIds, missingSettlementIds },
    geometry,
    fingerprint: {
      terrain: layers.terrain.valid ? fnv32(world.terrain) : null,
      owner: layers.owner.valid ? fnv32(world.owner) : null,
      politicalOwner: world?.politicalOwnerMap instanceof Uint8Array ? fnv32(world.politicalOwnerMap) : null,
      terrainCombined: layers.terrain.valid ? (h >>> 0).toString(16).padStart(8, '0') : null,
    },
    errors,
    warnings,
    result: errors.length ? 'NEEDS_REPAIR' : warnings.length ? 'STRUCTURE_OK_WITH_GAPS' : 'STRUCTURE_OK',
  };
}

export async function runAudit(argv = process.argv.slice(2)) {
  const readFlag = (flag, fallback) => {
    const pos = argv.indexOf(flag);
    return pos >= 0 && argv[pos + 1] ? argv[pos + 1] : fallback;
  };
  const seed = Number(readFlag('--seed', '1337'));
  if (!Number.isSafeInteger(seed)) throw new Error('--seed must be a safe integer');
  const output = readFlag('--output', 'output/reports/world-integrity.json');
  const report = auditWorldData(new WorldGenerator(seed).generateMapData());
  const path = resolve(output);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify(report, null, 2) + '\n');
  console.log('[world-integrity] ' + JSON.stringify({
    result: report.result, seed, tiles: report.dimensions.tiles,
    settlements: report.settlements.count, roads: report.geometry.roads.segments,
    rivers: report.geometry.rivers.segments, crossings: report.geometry.crossings.points,
    errors: report.errors.length, warnings: report.warnings.length, output: path,
  }));
  if (argv.includes('--strict') && report.errors.length) process.exitCode = 1;
  return report;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  runAudit().catch((err) => {
    console.error('[world-integrity] Fatal audit failure:', err);
    process.exitCode = 1;
  });
}
